/**
 * The labelled offline retrieval corpus (2.4, spec §5.2): 200 short records
 * of a fictional company handbook, 25 topics of 8 records each. Topics share
 * vocabulary on purpose (days, approvals, limits, requests), so a query has
 * near misses as well as answers. Fixed data: change it only with the
 * baseline in `retrieval-corpus.test.ts`.
 */

export interface RetrievalRecord {
  /** `<topic>-<n>`. */
  id: string;
  topic: string;
  text: string;
}

