/** The 200 records: 25 topics × 8. */
export const RETRIEVAL_RECORDS: readonly RetrievalRecord[] = Object.entries(TOPICS).flatMap(
  ([topic, texts]) => texts.map((text, index) => ({ id: `${topic}-${index + 1}`, topic, text })),
);
